import{_ as o,C as n,o as s,c as i,j as a,a as l,E as d,a3 as r}from"./chunks/framework.B3OtXxrP.js";const f=JSON.parse('{"title":"Install","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md"}'),c={name:"guide/install.md"};function p(h,e,m,u,g,b){const t=n("DownloadButtons");return s(),i("div",null,[e[0]||(e[0]=a("h1",{id:"install",tabindex:"-1"},[l("Install "),a("a",{class:"header-anchor",href:"#install","aria-label":'Permalink to "Install"'},"​")],-1)),d(t),e[1]||(e[1]=r('<h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><p>Blank is not notarized by Apple, so macOS blocks it the first time you open it. To allow it:</p><ul><li><strong>macOS 15 (Sequoia) or newer:</strong> try to open Blank once, then go to <strong>System Settings → Privacy &amp; Security</strong> and click <strong>Open Anyway</strong>.</li><li><strong>macOS 14 or older:</strong> right-click <code>blank.app</code> in Applications, choose <strong>Open</strong>, then confirm with <strong>Open</strong>.</li><li><strong>Terminal:</strong> run <code>xattr -dr com.apple.quarantine /Applications/blank.app</code>.</li></ul><details class="details custom-block"><summary>macOS says &quot;blank is damaged and can&#39;t be opened&quot;</summary><p>Blank v1.2.0 and older is not fully signed, so macOS does not offer <strong>Open Anyway</strong> for these versions. Only the Terminal command above works.</p></details><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>Download the <code>.msi</code> installer, or the <code>.exe</code> if you prefer a setup wizard. Both install the same app.</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><p>Blank needs glibc 2.35 or newer and WebKitGTK 4.1, e.g. Ubuntu 22.04+ or Debian 12+.</p><ul><li><strong>Debian, Ubuntu:</strong> <code>sudo apt install ./blank_*_amd64.deb</code></li><li><strong>Fedora:</strong> <code>sudo dnf install ./blank-*.x86_64.rpm</code></li><li><strong>openSUSE:</strong> <code>sudo zypper install ./blank-*.x86_64.rpm</code></li><li><strong>Any distribution:</strong> make the AppImage executable with <code>chmod +x blank_*.AppImage</code> and run it. AppImages need FUSE 2, which newer Ubuntu releases don&#39;t install by default: <code>sudo apt install libfuse2t64</code> (Ubuntu 24.04+) or <code>libfuse2</code> (older).</li></ul><p>The <code>.deb</code> and <code>.rpm</code> put Blank in your app menu and in <strong>Open With</strong> for markdown and Word files. Right-click any <code>.md</code> file and choose <strong>Open With → Blank</strong>, or set it as the default app for markdown there and open your notes with a double-click. A <code>.docx</code> opens as a new markdown document and the Word file stays as it is, see <a href="./writing#open-word-documents">Open Word documents</a>.</p><h2 id="open-a-file-from-the-terminal" tabindex="-1">Open a file from the terminal <a class="header-anchor" href="#open-a-file-from-the-terminal" aria-label="Permalink to &quot;Open a file from the terminal&quot;">​</a></h2><p>Pass a path to open a markdown file directly:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-yZiob" id="tab-vmSe8zV" checked><label data-title="Linux" for="tab-vmSe8zV">Linux</label><input type="radio" name="group-yZiob" id="tab-alNmA40"><label data-title="macOS" for="tab-alNmA40">macOS</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blank</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Documents/notes.md</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/Applications/blank.app/Contents/MacOS/blank</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Documents/notes.md</span></span></code></pre></div></div></div><p>With a path, <code>Mod</code> <code>S</code> saves to that file right away.</p>',14))])}const y=o(c,[["render",p]]);export{f as __pageData,y as default};
